--- a/training/level-2/L2-007-bookmark-store/bookmarkStore.mjs
+++ b/training/level-2/L2-007-bookmark-store/bookmarkStore.mjs
@@ -0,0 +1,204 @@
+// Import required modules
+import { join } from 'path';
+import { promises as fs } from 'fs';
+import { URL } from 'url';
+
+// Define constants
+const STATE_CORRUPT = 'STATE_CORRUPT';
+const INVALID_BOOKMARK = 'INVALID_BOOKMARK';
+const DUPLICATE_ID = 'DUPLICATE_ID';
+const INVALID_PATCH = 'INVALID_PATCH';
+const NOT_FOUND = 'NOT_FOUND';
+
+// Helper function to normalize URL
+function normalizeUrl(url) {
+  try {
+    const parsed = new URL(url);
+    return parsed.toString().replace(/#.*/, '');
+  } catch (e) {
+    throw new Error('Invalid URL');
+  }
+}
+
+// Helper function to validate bookmark
+function validateBookmark(bookmark) {
+  if (!bookmark || typeof bookmark !== 'object') {
+    throw new Error(INVALID_BOOKMARK);
+  }
+
+  const { id, title, url, tags } = bookmark;
+
+  if (typeof id !== 'string' || id.trim() === '') {
+    throw new Error(DUPLICATE_ID);
+  }
+
+  if (typeof title !== 'string' || title.trim() === '') {
+    throw new Error(INVALID_BOOKMARK);
+  }
+
+  if (typeof url !== 'string' || url.trim() === '') {
+    throw new Error(INVALID_BOOKMARK);
+  }
+
+  try {
+    normalizeUrl(url);
+  } catch (e) {
+    throw new Error(INVALID_BOOKMARK);
+  }
+
+  if (!Array.isArray(tags) || tags.some(tag => typeof tag !== 'string' || tag.trim() === '')) {
+    throw new Error(INVALID_BOOKMARK);
+  }
+}
+
+// Helper function to deep clone
+function deepClone(obj) {
+  return JSON.parse(JSON.stringify(obj));
+}
+
+// CreateBookmarkStore function
+async function createBookmarkStore(filePath) {
+  // Ensure the directory exists
+  const dirPath = join(...filePath.split('/').slice(0, -1));
+  try {
+    await fs.mkdir(dirPath, { recursive: true });
+  } catch (e) {
+    if (e.code !== 'EEXIST') {
+      throw e;
+    }
+  }
+
+  // Load existing bookmarks
+  let bookmarks = [];
+  try {
+    const data = await fs.readFile(filePath, 'utf-8');
+    bookmarks = JSON.parse(data);
+  } catch (e) {
+    if (e.code !== 'ENOENT') {
+      throw e;
+    }
+  }
+
+  // Validate bookmarks
+  if (!Array.isArray(bookmarks)) {
+    throw new Error(STATE_CORRUPT);
+  }
+
+  // Create a temporary file for writing
+  const tempFilePath = filePath + '.tmp';
+
+  // List all bookmarks
+  async function list() {
+    return deepClone(bookmarks);
+  }
+
+  // Get a bookmark by ID
+  async function get(id) {
+    const bookmark = bookmarks.find(b => b.id === id);
+    if (!bookmark) {
+      throw new Error(NOT_FOUND);
+    }
+    return deepClone(bookmark);
+  }
+
+  // Add a new bookmark
+  async function add(bookmark) {
+    validateBookmark(bookmark);
+
+    if (bookmarks.some(b => b.id === bookmark.id)) {
+      throw new Error(DUPLICATE_ID);
+    }
+
+    bookmarks.push(bookmark);
+
+    // Write to temporary file
+    await fs.writeFile(tempFilePath, JSON.stringify(bookmarks, null, 2), 'utf-8');
+
+    // Rename temporary file to the original
+    await fs.rename(tempFilePath, filePath);
+
+    return deepClone(bookmark);
+  }
+
+  // Update an existing bookmark
+  async function update(id, patch) {
+    const bookmark = bookmarks.find(b => b.id === id);
+    if (!bookmark) {
+      throw new Error(NOT_FOUND);
+    }
+
+    // Validate patch
+    if (typeof patch !== 'object' || patch === null) {
+      throw new Error(INVALID_PATCH);
+    }
+
+    const updatedBookmark = { ...bookmark };
+
+    if (patch.title !== undefined) {
+      if (typeof patch.title !== 'string' || patch.title.trim() === '') {
+        throw new Error(INVALID_PATCH);
+      }
+      updatedBookmark.title = patch.title.trim();
+    }
+
+    if (patch.url !== undefined) {
+      if (typeof patch.url !== 'string' || patch.url.trim() === '') {
+        throw new Error(INVALID_PATCH);
+      }
+      try {
+        updatedBookmark.url = normalizeUrl(patch.url);
+      } catch (e) {
+        throw new Error(INVALID_PATCH);
+      }
+    }
+
+    if (patch.tags !== undefined) {
+      if (!Array.isArray(patch.tags) || patch.tags.some(tag => typeof tag !== 'string' || tag.trim() === '')) {
+        throw new Error(INVALID_PATCH);
+      }
+      updatedBookmark.tags = patch.tags;
+    }
+
+    // Update the bookmark
+    const index = bookmarks.findIndex(b => b.id === id);
+    bookmarks[index] = updatedBookmark;
+
+    // Write to temporary file
+    await fs.writeFile(tempFilePath, JSON.stringify(bookmarks, null, 2), 'utf-8');
+
+    // Rename temporary file to the original
+    await fs.rename(tempFilePath, filePath);
+
+    return deepClone(updatedBookmark);
+  }
+
+  // Remove a bookmark by ID
+  async function remove(id) {
+    const index = bookmarks.findIndex(b => b.id === id);
+    if (index === -1) {
+      throw new Error(NOT_FOUND);
+    }
+
+    const removedBookmark = bookmarks.splice(index, 1)[0];
+
+    // Write to temporary file
+    await fs.writeFile(tempFilePath, JSON.stringify(bookmarks, null, 2), 'utf-8');
+
+    // Rename temporary file to the original
+    await fs.rename(tempFilePath, filePath);
+
+    return deepClone(removedBookmark);
+  }
+
+  // Export the API
+  return {
+    list,
+    get,
+    add,
+    update,
+    remove
+  };
+}
+
+// Export the createBookmarkStore function
+export { createBookmarkStore };

